import math
from attrs import define, field

@define
class onepole:
    cutoff: float = field(default = 1000.0)     # Hz

    _fs: float = field(init = False, default = 48000.0)
    _y:  float = field(init = False, default = 0.0)

    def prepare(self, sample_rate: float, vector_size: int) -> None:
        self._fs = sample_rate

    def process(self, x: float) -> float:
        a = math.exp(-2.0 * math.pi * self.cutoff / self._fs)
        self._y = (1.0 - a) * x + a * self._y
        return self._y
